const b = $input.first().json.body || {};
const pi = b.personalInfo || b.personal_info || {};
function esc(v) {
  return String(v === undefined || v === null ? '' : v)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}
function arr(v) { return Array.isArray(v) ? v : (v ? [v] : []); }
function txt(o, keys) {
  for (const k of keys) { if (o && o[k]) { return String(o[k]); } }
  return '';
}
function dates(o) {
  const range = txt(o, ['dates', 'period', 'duration', 'years']);
  if (range) { return range; }
  const st = txt(o, ['startDate', 'start', 'from']);
  const en = txt(o, ['endDate', 'end', 'to']) || (st ? 'Present' : '');
  return st ? (st + ' - ' + en) : en;
}
function bullets(o) {
  let d = o.bullets || o.achievements || o.highlights || o.description || o.details || '';
  if (!Array.isArray(d)) { d = String(d).split(String.fromCharCode(10)); }
  const items = d.map(function (x) { return String(x).replace(/^[-*] */, '').trim(); }).filter(Boolean);
  if (!items.length) { return ''; }
  return '<ul>' + items.map(function (x) { return '<li>' + esc(x) + '</li>'; }).join('') + '</ul>';
}
function section(title, body) {
  return body ? '<section><h2>' + esc(title) + '</h2>' + body + '</section>' : '';
}
function entry(head, sub, right, extra) {
  return '<div class="entry"><div class="row"><div><span class="h">' + esc(head) + '</span>' +
    (sub ? '<span class="sub"> | ' + esc(sub) + '</span>' : '') + '</div>' +
    (right ? '<div class="date">' + esc(right) + '</div>' : '') + '</div>' + (extra || '') + '</div>';
}
const name = txt(pi, ['fullName', 'name']) || 'Your Name';
const title = txt(pi, ['title', 'jobTitle', 'headline']);
const contact = [pi.email, pi.phone, pi.location, pi.linkedin, pi.portfolio || pi.website]
  .filter(Boolean).map(function (x) { return '<span>' + esc(x) + '</span>'; }).join('<i></i>');

const exp = arr(b.experience).map(function (e) {
  if (typeof e === 'string') { return '<div class="entry"><p>' + esc(e) + '</p></div>'; }
  return entry(txt(e, ['title', 'role', 'position', 'jobTitle']), txt(e, ['company', 'employer', 'organization']), dates(e), bullets(e));
}).join('');
const edu = arr(b.education).map(function (e) {
  if (typeof e === 'string') { return '<div class="entry"><p>' + esc(e) + '</p></div>'; }
  const deg = [txt(e, ['degree', 'qualification']), txt(e, ['field', 'major', 'fieldOfStudy'])].filter(Boolean).join(', ');
  const extra = txt(e, ['description', 'details', 'honors', 'gpa']);
  return entry(deg || txt(e, ['title']), txt(e, ['school', 'institution', 'university']), dates(e) || txt(e, ['year', 'graduationYear']), extra ? '<p>' + esc(extra) + '</p>' : '');
}).join('');
let skillsArr = b.skills;
if (typeof skillsArr === 'string') { skillsArr = skillsArr.split(','); }
const skills = arr(skillsArr).map(function (x) {
  return typeof x === 'string' ? x.trim() : txt(x, ['name', 'skill']);
}).filter(Boolean).map(function (x) { return '<span class="chip">' + esc(x) + '</span>'; }).join('');
const proj = arr(b.projects).map(function (e) {
  if (typeof e === 'string') { return '<div class="entry"><p>' + esc(e) + '</p></div>'; }
  const tech = arr(e.technologies || e.tech || e.stack).join(', ');
  const link = txt(e, ['link', 'url']);
  const extra = bullets(e) + (tech ? '<p class="meta">Tech: ' + esc(tech) + '</p>' : '') + (link ? '<p class="meta">' + esc(link) + '</p>' : '');
  return entry(txt(e, ['name', 'title']), '', dates(e), extra);
}).join('');
const cert = arr(b.certifications).map(function (e) {
  if (typeof e === 'string') { return '<div class="entry"><p>' + esc(e) + '</p></div>'; }
  return entry(txt(e, ['name', 'title']), txt(e, ['issuer', 'organization']), txt(e, ['date', 'year', 'issued']), '');
}).join('');
const summary = b.summary ? '<p>' + esc(b.summary) + '</p>' : '';

const css = '@page{size:A4}*{box-sizing:border-box}body{margin:0;font-family:Helvetica,Arial,sans-serif;color:#1f2937;font-size:10.5pt;line-height:1.5}' +
  '.wrap{padding:0 16mm}header{background:#0f2744;color:#fff;padding:12mm 16mm 9mm}header h1{margin:0;font-size:25pt;letter-spacing:.5px}' +
  '.title{margin-top:2px;font-size:12pt;color:#9bc1ee}.contact{margin-top:8px;font-size:9.5pt;color:#dbe7f5}.contact i{display:inline-block;width:4px;height:4px;border-radius:2px;background:#9bc1ee;margin:0 9px;vertical-align:middle}' +
  'section{margin-top:16px}h2{margin:0 0 8px;font-size:11pt;text-transform:uppercase;letter-spacing:1.5px;color:#0f2744;border-bottom:2px solid #2f6fb5;padding-bottom:3px}' +
  '.entry{margin-bottom:10px;page-break-inside:avoid}.row{display:flex;justify-content:space-between;align-items:baseline}.h{font-weight:bold;color:#111827}.sub{color:#2f6fb5;font-weight:bold}.date{color:#6b7280;font-size:9.5pt;white-space:nowrap}' +
  'ul{margin:4px 0 0;padding-left:18px}li{margin-bottom:2px}p{margin:4px 0}.meta{color:#6b7280;font-size:9.5pt}.chip{display:inline-block;background:#e8f0fa;color:#0f2744;border-radius:10px;padding:2px 10px;margin:0 6px 6px 0;font-size:9.5pt}';

const html = '<!DOCTYPE html><html><head><meta charset="utf-8"><style>' + css + '</style></head><body>' +
  '<header><h1>' + esc(name) + '</h1>' + (title ? '<div class="title">' + esc(title) + '</div>' : '') +
  '<div class="contact">' + contact + '</div></header><div class="wrap">' +
  section('Summary', summary) + section('Experience', exp) + section('Education', edu) +
  section('Skills', skills) + section('Projects', proj) + section('Certifications', cert) +
  '</div></body></html>';

const rid = b.resumeId || b.resume_id || '';
const safe = (name || 'resume').replace(/[^a-zA-Z0-9]+/g, '_').replace(/^_+|_+$/g, '') || 'resume';
return [{ json: { html: html, resume_id: rid, file_name: safe + '_Resume.pdf' } }];

parameters.text:
=Review this resume and produce improvement suggestions per section.

RESUME (JSON):
{{ JSON.stringify($("Normalize Resume").item.json.resume, null, 2) }}

=Pick 3 job search keywords for jobinja.ir from this resume.

RESUME (JSON):
{{ JSON.stringify($("Normalize Resume").first().json.resume, null, 2) }}

parameters.jsCode:
const out = ($input.first().json.output || {});
let list = (Array.isArray(out.keywords) ? out.keywords : []).map(function (k) { return String(k || '').trim(); }).filter(Boolean);
if (!list.length) {
  const r = $('Normalize Resume').first().json.resume || {};
  const e = (r.experience || [])[0] || {};
  const s = (r.skills || [])[0];
  const fb = e.title || e.role || e.position || (r.personalInfo || {}).title || (typeof s === 'string' ? s : (s || {}).name) || '';
  if (fb) { list = [String(fb)]; }
}
if (!list.length) { list = ['developer']; }
return list.slice(0, 3).map(function (k) {
  return { json: { keyword: k, url: 'https://jobinja.ir/jobs?filters%5Bkeywords%5D%5B0%5D=' + encodeURIComponent(k) } };
});

function clean(s) {
  return String(s || '').replace(/<[^>]*>/g, ' ').replace(/&zwnj;/g, String.fromCharCode(8204)).replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ').trim();
}
function parseList(html) {
  const parts = html.split('c-jobListView__item ').slice(1);
  const jobs = [];
  for (const p of parts) {
    const t = p.match(/c-jobListView__titleLink"[^>]*href="([^"]+)"[^>]*>([\s\S]*?)<\/a>/);
    if (!t) { continue; }
    const url = t[1].replace(/&amp;/g, '&').split('?')[0];
    const comp = p.match(/c-icon--construction"><\/i>\s*<span>([\s\S]*?)<\/span>/);
    const place = p.match(/c-icon--place"><\/i>\s*<span>([\s\S]*?)<\/span>/);
    const contract = p.match(/c-icon--resume"><\/i>\s*<span>\s*<span>([\s\S]*?)<\/span>/);
    const days = p.match(/c-jobListView__passedDays">([\s\S]*?)<\/span>/);
    jobs.push({
      title: clean(t[2]),
      company: comp ? clean(comp[1]) : '',
      location: place ? clean(place[1]) : '',
      contract: contract ? clean(contract[1]) : '',
      posted: days ? clean(days[1]).replace(/[()]/g, '').trim() : '',
      url: url
    });
  }
  return jobs;
}
const lists = $input.all().map(function (i) { return parseList(String(i.json.data || '')); });
const seen = {};
const picked = [];
for (let round = 0; round < 25 && picked.length < 3; round++) {
  for (const l of lists) {
    const j = l[round];
    if (j && !seen[j.url] && picked.length < 3) { seen[j.url] = true; picked.push(j); }
  }
}
return [{ json: { jobs: picked } }];

function clean(s) {
  return String(s || '').replace(/<[^>]*>/g, ' ').replace(/&zwnj;/g, String.fromCharCode(8204)).replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&nbsp;/g, ' ').replace(/&#?[a-z0-9]+;/gi, ' ').replace(/\s+/g, ' ').trim();
}
function shorten(s, n) {
  if (s.length <= n) { return s; }
  const cut = s.slice(0, n);
  const sp = cut.lastIndexOf(' ');
  return (sp > n * 0.6 ? cut.slice(0, sp) : cut) + '...';
}
const jobs = ($('Parse Jobs').first().json.jobs || []);
const det = $input.all();
const result = jobs.map(function (j, idx) {
  const html = String((det[idx] && det[idx].json && det[idx].json.data) || '');
  let desc = '';
  const k = html.indexOf('s-jobDesc');
  if (k >= 0) { desc = clean(html.slice(k, k + 9000).replace(/^[^>]*>/, '')); }
  if (!desc) { desc = [j.contract, j.posted].filter(Boolean).join(' - '); }
  return { title: j.title, company: j.company, location: j.location, description: shorten(desc, 220), url: j.url };
});
return [{ json: { job_suggestions: result } }];
